     8	    private static final BigDecimal FIRST_INSURANCE_SURCHARGE_RATE = rate(10);
     9	    private static final BigDecimal CURSE_SURCHARGE_RATE = rate(50);
    10	    private static final BigDecimal HIGH_ENCHANTMENT_SURCHARGE_RATE = rate(30);
    11	
    12	    private static final BigDecimal LOYALTY_DISCOUNT_RATE = rate(20);
    13	
    14	    /** From this many years of business on, the MHPCO calls a customer long-standing. */
    15	    private static final int LONG_STANDING_YEARS = 2;
    16	
    17	    /** From this enchantment level on, the MHPCO considers an item highly enchanted. */
    18	    private static final int HIGH_ENCHANTMENT_LEVEL = 5;
    19	
    20	    private final Customer customer;
    21	
    22	    public ClaimOffice(Customer customer) {
    23	        this.customer = customer;
    24	    }
    25	
    26	    public int quote(List<Item> items) {
    27	        BigDecimal policyBasePremium = MhpcoPriceList.policyBasePremiumOf(items);
    28	        BigDecimal premiumBeforeFee = policyScopeContribution(policyBasePremium)
    29	                .add(itemScopeContribution(items));
    30	        return roundInOfficeFavour(premiumBeforeFee.add(PROCESSING_FEE));
    31	    }
    32	
    33	    /**
    34	     * What the item scope contributes: the MHPCO charges a risk surcharge for each
    35	     * risky item as a share of that item's own base premium, never of the policy total.
    36	     */
    37	    private static BigDecimal itemScopeContribution(List<Item> items) {
    38	        return items.stream()
    39	                .map(ClaimOffice::riskSurchargeFor)
    40	                .reduce(BigDecimal.ZERO, BigDecimal::add);
    41	    }
    42	
    43	    private static BigDecimal riskSurchargeFor(Item item) {
    44	        BigDecimal itemBasePremium = MhpcoPriceList.basePremiumOf(item);
    45	        BigDecimal surcharge = BigDecimal.ZERO;
    46	        if (item.cursed()) {
    47	            surcharge = surcharge.add(shareOf(itemBasePremium, CURSE_SURCHARGE_RATE));
    48	        }
    49	        if (isHighlyEnchanted(item)) {
    50	            surcharge = surcharge.add(
    51	                    shareOf(itemBasePremium, HIGH_ENCHANTMENT_SURCHARGE_RATE));
    52	        }
    53	        return surcharge;
    54	    }
    55	
    56	    private static boolean isHighlyEnchanted(Item item) {
    57	        return item.enchantment() >= HIGH_ENCHANTMENT_LEVEL;
    58	    }
    59	
    60	    /**
    61	     * What the policy scope contributes: the policy base premium itself, adjusted by
    62	     * the modifiers the office applies to the policy as a whole.
    63	     */
    64	    private BigDecimal policyScopeContribution(BigDecimal policyBasePremium) {
    65	        BigDecimal contribution = policyBasePremium
    66	                .add(shareOf(policyBasePremium, FIRST_INSURANCE_SURCHARGE_RATE));
    67	        if (isLongStanding(customer)) {
    68	            contribution = contribution
    69	                    .subtract(shareOf(policyBasePremium, LOYALTY_DISCOUNT_RATE));
    70	        }
    71	        return contribution;
    72	    }
    73	
    74	    private static boolean isLongStanding(Customer customer) {
    75	        return customer.yearsWithMHPCO() >= LONG_STANDING_YEARS;
    76	    }
    77	
    78	    /** A modifier is a percentage share of the amount it applies to. */
    79	    private static BigDecimal shareOf(BigDecimal amount, BigDecimal modifierRate) {
    80	        return amount.multiply(modifierRate);
    81	    }
    82	
    83	    /** A modifier rate stated the way the price list states it: in whole percent. */
    84	    private static BigDecimal rate(int percent) {
    85	        return BigDecimal.valueOf(percent, 2);
    86	    }
