    89	     * A premium is rounded up: the MHPCO rounds in its own favour. Intermediate
    90	     * amounts stay exact fractions, so only this final step loses the remainder.
    91	     */
    92	    private static int roundInOfficeFavour(BigDecimal premium) {
    93	        return premium.setScale(0, RoundingMode.CEILING).intValueExact();
    94	    }
